const S={mode:savedMode==='Live'?'Live':'Demo',available:['Demo'],aiGlass:prefs.aiGlass===true,theme:themes.includes(prefs.theme)?prefs.theme:'graphite',lang:['en','da'].includes(prefs.lang)?prefs.lang:'en',seq:0,dirty:false,saving:false,period:'1m',currency:'DKK',accounts:[],categories:[],suggestions:null,offset:0,filters:{},goal:null,budget:null,route:'overview'};
