const timestamp=x=>x?new Intl.DateTimeFormat(locale(),{timeZone:'Europe/Copenhagen',dateStyle:'medium',timeStyle:'short'}).format(new Date(x)):'—';
const amountText=(n,options={})=>new Intl.NumberFormat(locale(),{minimumFractionDigits:2,maximumFractionDigits:2,...options}).format(n);
const moneyText=(n,c=S.currency)=>n==null?'—':`${amountText(n)} ${c}`;
const money=(n,c=S.currency,options={})=>n==null?'—':`<span class="money">${amountText(n,options)}<span class="money-currency"> ${e(c)}</span></span>`;
