const shift=(d,days)=>{const a=new Date(d+'T12:00:00Z');a.setUTCDate(a.getUTCDate()+days);return a.toISOString().slice(0,10);};
const monthShift=(d,n)=>{const a=new Date(d+'T12:00:00Z'),day=a.getUTCDate();a.setUTCDate(1);a.setUTCMonth(a.getUTCMonth()+n);const last=new Date(Date.UTC(a.getUTCFullYear(),a.getUTCMonth()+1,0)).getUTCDate();a.setUTCDate(Math.min(day,last));return a.toISOString().slice(0,10);};
