function errorText(err){if(err.code==='ACCOUNT_ALREADY_HAS_GOAL')return t('This account already has a goal. Choose another account.');if(err.code==='DEDICATED_ACCOUNT_REQUIRED')return t('Choose a dedicated account');if(err.code==='REVIEW_ITEM_CHANGED')return t('This item changed. Refresh the queue before trying again.');if(err.code==='REVIEW_UNDO_CONFLICT')return t('This item has newer changes. Undo was not applied.');if(err.code==='VERSION_CONFLICT')return t('Keep your changes and reload the latest version before trying again.');if(err.status===400)return t('Check the form fields.')+' '+err.code;return t('This request could not be completed.')+(err.code?' '+err.code:'');}
async function api(path,options={}){
 const seq=S.seq,mode=S.mode;const res=await fetch('/api/'+path,{credentials:'same-origin',cache:'no-store',...options,headers:{'X-Banking-Client':'web','X-Banking-Mode':mode,...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});
 if(seq!==S.seq||mode!==S.mode)throw {stale:true};
 if(res.status===401){S.seq++;budgetUI.clear();S.accounts=[];S.accountBalances=null;S.overviewInfo=null;S.categories=[];S.accountView=null;S.review=null;S.reviewData=null;S.reviewHistory=null;S.reviewSelected=[];S.reviewCount=null;S.goal=null;S.budget=null;S.suggestions=null;S.draftSuggestion=null;S.transactions=[];S.connections=[];S.budgets=[];S.upcoming=null;dialog.close();locked();throw {stale:true};}
 const data=res.status===204?null:await res.json().catch(()=>null);
 if(seq!==S.seq||mode!==S.mode)throw {stale:true};
 if(!res.ok)throw {status:res.status,code:data?.error||'REQUEST_FAILED',details:data?.details};
 if(res.headers.get('X-Banking-Mode')!==mode)throw {stale:true};return data;
}
const post=(path,data,method='POST')=>api(path,{method,...(data!==undefined?{body:JSON.stringify(data)}:{})});
