function locked(){resetAdvisor();activeLoading?.cancel();activeLoading=null;S.seq++;budgetUI.clear();S.accounts=[];S.accountBalances=null;S.overviewInfo=null;S.categories=[];S.accountView=null;S.review=null;S.reviewData=null;S.reviewHistory=null;S.reviewSelected=[];S.reviewCount=null;S.goal=null;S.budget=null;S.suggestions=null;S.draftSuggestion=null;S.transactions=[];S.connections=[];S.budgets=[];S.upcoming=null;dialog.close();try{sessionStorage.removeItem('banking.workspace');}catch{}S.owner=false;S.mode='Demo';S.available=['Demo'];access.show();}

const button=(label,action,extra='',kind='')=>`<button type="button" class="${kind}" data-action="${action}" ${extra}>${t(label)}</button>`;
const opts=(items,value)=>items.map(([id,label])=>`<option value="${e(id)}" ${String(id)===String(value)?'selected':''}>${e(label)}</option>`).join('');
const select=(name,label,items,value,attr='')=>`<div class="field"><label for="${name}">${t(label)}</label><select id="${name}" name="${name}" ${attr}>${opts(items,value)}</select></div>`;
const input=(name,label,value='',type='text',attr='')=>`<div class="field"><label for="${name}">${t(label)}</label><input id="${name}" name="${name}" type="${type}" value="${e(value)}" ${attr}></div>`;
const empty=(title,body,actions='')=>`<div class="empty"><h2>${t(title)}</h2><p>${t(body)}</p><div class="actions">${actions}</div></div>`;
const collectionEmpty=(kind,title,description,actions)=>`<section class="collection-empty"><div class="collection-empty-icon" aria-hidden="true">${icon(kind)}</div><h2>${t(title)}</h2><p>${t(description)}</p><div class="collection-empty-actions">${actions}</div></section>`;
