const bankDetailsUI=createBankDetailsUI({S,api,t,e,date,money,moneyText,dialog,button,accountName});
const currencyItems=()=>[...new Set(['DKK',...S.accounts.map(x=>x.currency)])].sort().map(x=>[x,x]);
function syncLabel(){const last=S.accounts.map(a=>a.lastSuccess).filter(Boolean).sort()[0];return `${t("Last sync")}: ${last?timestamp(last):t("Not available")}`;}
function accountSelector(){return `<div class="account-select"><details class="account-menu"><summary aria-label="${t('Account menu')}"><span class="avatar">${S.mode==='Live'?'DA':'DE'}</span><span class="account-row-name">${S.mode==='Live'?'Dan':'Demo'}</span><span class="account-row-options" aria-hidden="true">${icon('more')}</span></summary><div class="account-menu-list"><p class="account-sync" data-account-sync>${syncLabel()}</p><nav aria-label="${t('Account actions')}"><a href="#/settings">${icon('settings')}<span>${t('Settings')}</span></a><a href="#/connections">${icon('connections')}<span>${t('Connections')}</span></a><button type="button" data-action="logout">${icon('profile')}<span>${t('Sign out')}</span></button></nav></div></details></div>`;}

function navlink(name,key){return `<a href="#/${key}" aria-label="${e(t(name))}" title="${e(t(name))}" class="${S.route===key?'selected':''}" ${S.route===key?'aria-current="page"':''}>${icon(key)}<span>${t(name)}</span>${key==='review'?`<span class="nav-count" data-review-count>${S.reviewCount||''}</span>`:''}</a>`;}
const mainNav=()=>[['360','overview'],['Accounts','accounts'],['Review','review'],['Budgets','budgets'],['Goals','goals'],['Advisor','advisor']].map(x=>navlink(...x)).join('');
function shell(content='',focused=false){
 activeLoading?.cancel();activeLoading=null;
 try{document.documentElement.classList.toggle('nav-collapsed',localStorage.getItem('banking.navCollapsed')==='true');}catch{}
 const settings=S.route==='settings';
 ensureBrandMark();
 app.innerHTML=`<aside class="sidebar ${settings?'settings-sidebar':''}"><div class="sidebar-heading">${brand()}<button class="sidebar-toggle" type="button" data-action="toggle-sidebar" aria-label="${S.lang==='da'?'Skift sidepanel':'Toggle sidebar'}" aria-expanded="${!document.documentElement.classList.contains('nav-collapsed')}"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="3"/><path d="M9 4v16m6-11-3 3 3 3"/></svg></button></div>${settings?`<a class="back-link" href="#/overview">← ${t('Back to Overview')}</a><div class="nav-label">${t('Settings')}</div><nav class="nav">${['profile','language','appearance'].map(x=>`<a href="#/settings/${x}" aria-label="${t(x[0].toUpperCase()+x.slice(1))}" title="${t(x[0].toUpperCase()+x.slice(1))}" class="${S.section===x?'selected':''}">${icon(x)}<span>${t(x[0].toUpperCase()+x.slice(1))}</span></a>`).join('')}</nav>`:`<nav class="nav">${mainNav()}<div class="nav-label">${t('Wealth')}</div>${navlink('Investments','investments')}${navlink('Pension','pension')}${navlink('Markets','markets')}<div class="nav-label">${t('Debt')}</div>${navlink('Loans','loans')}<div class="nav-label">${t('AI workspace')}</div>${navlink('Analysis','analysis')}${navlink('Memory','memory')}</nav>`}${accountSelector()}</aside><main id="main" tabindex="-1" class="main ${settings?'settings-main':''} ${focused?'focused':''}"><div class="mobile-top">${brand()}</div>${content}</main>${!settings&&!focused?`<nav class="bottom-nav" aria-label="${t('More')}">${[['360','overview'],['Accounts','accounts'],['Review','review']].map(x=>navlink(...x)).join('')}<button data-action="more" class="${!['overview','accounts','review'].includes(S.route)?'selected':''}">${icon('more')}<span>${t('More')}</span></button></nav>`:''}`;
 return document.querySelector('#main');
}
function header(title,controls=''){return `<header class="page-head${["360","Overview","Accounts","Review","Budgets","Goals","Markets","Investments","Pension"].includes(title)?" scenic-page-head":""}" data-scene="${dayScene()}"><div><h1>${t(title)}</h1></div>${controls?`<div class="controls">${controls}</div>`:''}</header>`;}
function sectionAction(label,href='',action=''){
 const content=`<span>${t(label)}</span><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-5-5 5 5-5 5"/></svg>`;
 return href?`<a class="text-action" href="${e(href)}">${content}</a>`:`<button type="button" class="text-action" data-action="${e(action)}">${content}</button>`;
}
function periodControls(includeCurrency=true){const r=range();return select('period','Period',[['1w',t('1 week')],['1m',t('1 month')],['3m',t('3 months')],['6m',t('6 months')],['1y',t('1 year')],['custom',t('Custom')]],S.period,'data-action="period"')+(includeCurrency?select('currency','Currency',currencyItems(),S.currency,'data-action="currency"'):'')+(S.period==='custom'?`<div class="custom-range">${input('from','From',r.from,'date')}${input('to','To',r.to,'date')}${button('Apply','range')}</div>`:'');}
function statusName(x){return {OnTrack:'On track',AtRisk:'At risk',BehindPlan:'Behind plan',Reached:'Reached',Unknown:'Unknown'}[x]||'Unknown';}
function statusClass(x){return ['OnTrack','Reached'].includes(x)?'positive':x==='AtRisk'?'warning':x==='BehindPlan'?'negative':'muted';}
function goalProgress(p){return `${charts.goal(p)}<div class="${statusClass(p.status)}"><div class="section-head"><span class="status">${p.status==='Unknown'?'○':p.status==='BehindPlan'?'↓':'●'} ${t(statusName(p.status))}</span></div></div><small>${money(p.measuredBalance,p.currency)} / ${money(p.target,p.currency)}</small>${p.reason?`<p><small>${t(({DEDICATED_ACCOUNT_REQUIRED:'Choose a dedicated account',NO_ACTIVE_PLAN:'No active plan',STALE_BALANCE:'Stale balance',MISSING_BOOKED_BALANCE:'Missing balance',MIXED_CURRENCY_REQUIRES_CONVERSION:'Multiple currencies cannot be combined without conversion.'})[p.reason]||'No data')}</small></p>`:''}`;}
function activityRows(items,editable=false){return `<div class="table-wrap" tabindex="0" role="region" aria-label="${t('Transactions')}"><table class="mobile-cards"><thead><tr><th>${t('Description')}</th><th>${t('Date')}</th><th>${t('Category')}</th><th class="amount">${t('Amount')}</th></tr></thead><tbody>${items.map(x=>`<tr><td class="transaction-title">${editable?`<button class="quiet" data-action="transaction" data-id="${x.id}">${e(x.description)}</button>`:e(x.description)}<small>${e(accountName(x.accountId))}${x.status!=='BOOK'?' · '+e(x.status==='PDNG'?t('Pending'):x.status):''}</small></td><td>${date(x.bookingDate||x.valueDate)}</td><td>${editable?`<select aria-label="${t('Category')} · ${e(x.description)}" data-action="classify" data-id="${x.id}" data-version="${e(x.version)}">${opts([['',t('Uncategorized')],...S.categories.map(c=>[c.id,c.name])],x.categoryId||'')}</select>`:e(S.categories.find(c=>c.id===x.categoryId)?.name||t('Uncategorized'))}</td><td class="amount ${x.amount>0?'positive':''}">${money(x.amount,x.currency)}</td></tr>`).join('')}</tbody></table></div>`;}
function overviewHeader(){return header('360',`<div class="w360-period-controls">${periodControls(false)}</div>`);}
async function overview(main, startup){
 let completed=0;
 const tracked = promise => promise.then(value=>{startup?.setProgress(25 + (++completed / 8) * 60);return value;});
 main.classList.add('panoramic-main');
 const r=range();const flowKey=S.overviewFlowPeriod||'1m';const flowRange={from:flowKey==='1w'?shift(today(),-6):shift(monthShift(today(),-({'1m':1,'3m':3,'6m':6,'1y':12}[flowKey]||1)),1),to:today()};window.dispatchEvent(new CustomEvent('banking:section-context',{detail:{section:'cashFlow',...flowRange,currency:S.currency}}));const flowInfoPromise=api(`account-insights?from=${flowRange.from}&to=${flowRange.to}&currency=${S.currency}`);const extra360=Promise.all([api('wealth/overview?currency='+S.currency).catch(()=>null),api(`cash-flow?from=${r.from}&to=${r.to}&currency=${S.currency}`).catch(()=>null),api((S.mode==='Demo'?'employee-stocks/demo/':'employee-stocks/')+'valuation').catch(()=>null)]);if(!main.querySelector('.page-head'))main.insertAdjacentHTML('beforeend',overviewHeader());if(!main.querySelector('#overview-data'))main.insertAdjacentHTML('beforeend',`<div id="overview-data"></div>`);
 const budgetData=budgetUI.loadOverview().then(value=>({value}),error=>({error}));
 const [trends,upcoming,goals,balances,info,review]=await Promise.all([api(`trends?from=${flowRange.from}&to=${flowRange.to}&currency=${S.currency}`),api(`upcoming-estimates?from=${today()}&days=7&currency=${S.currency}`),api('goals'),Promise.all(S.accounts.map(a=>api(`accounts/${a.id}/balances?limit=20`))),r.from===flowRange.from&&r.to===flowRange.to?flowInfoPromise:api(`account-insights?from=${r.from}&to=${r.to}&currency=${S.currency}`),api('review?limit=1')].map(tracked));
 S.upcoming=upcoming;S.overviewInfo=info;S.accountBalances=balances;
 const [progress,previous]=await Promise.all([Promise.all(goals.slice(0,3).map(g=>api(`goals/${g.id}/progress`))),api(`account-insights?from=${trends.previousFrom}&to=${trends.previousTo}&currency=${S.currency}`)].map(tracked));
 const selected=S.accounts.map((a,i)=>({account:a,balance:balances[i].find(b=>b.currency===S.currency&&['ITAV','CLAV'].includes(b.type))})).filter(x=>x.account.currency===S.currency);
 document.querySelectorAll('[data-account-sync]').forEach(el=>el.textContent=syncLabel());
 const total=selected.length&&selected.every(x=>x.balance)?selected.reduce((n,x)=>n+x.balance.amount,0):null;
 const data=main.querySelector('#overview-data');data.className='ov-dashboard';
 const flowInfo=await flowInfoPromise;
 overviewUI.render(data,{selected,total,trends,info:flowInfo,previous,upcoming,goals,progress,review,range:flowRange});
 data.querySelector('#ov-motion .ov-section-head, #ov-motion .section-head')?.insertAdjacentHTML('beforeend',select('overview-flow-period','Period',[['1w',t('1 week')],['1m',t('1 month')],['3m',t('3 months')],['6m',t('6 months')],['1y',t('1 year')]],flowKey,'data-action="overview-flow-period"'));

 const advisorSignals=[];
 const behind=progress.findIndex(p=>p.status==='BehindPlan');
 if(behind>=0)advisorSignals.push({label:goals[behind].name+' · '+(S.lang==='da'?'bagud med opsparingen':'behind plan'),prompt:(S.lang==='da'?'Forklar hvorfor dette gemte mål er bagud, og hvilke indbetalinger der mangler: ':'Explain why this saved goal is behind and which contributions are missing: ')+goals[behind].name});
 if(flowInfo.disposableAmount!=null&&flowInfo.disposableAmount<0)advisorSignals.push({label:S.lang==='da'?'Dit rådighedsbeløb er negativt':'Your available amount is negative',prompt:S.lang==='da'?'Forklar mit negative rådighedsbeløb i den valgte periode. Sammenlign med mit gemte budget og foreslå, hvad jeg kan undersøge. Gem ikke ændringer.':'Explain my negative available amount for the selected period. Compare with my saved budget and suggest what to investigate. Do not save changes.'});
 if(flowInfo.coverage.sufficientHistory&&previous.coverage.sufficientHistory){
  const increases=flowInfo.categories.map(c=>({...c,previous:previous.categories.find(p=>p.categoryId===c.categoryId)?.amount||0})).filter(c=>c.previous>0&&c.amount-c.previous>=100&&(c.amount-c.previous)/c.previous>=.1).sort((a,b)=>(b.amount-b.previous)-(a.amount-a.previous));
  if(increases.length){const c=increases[0],name=S.categories.find(x=>x.id===c.categoryId)?.name||t('Uncategorized');advisorSignals.push({label:name+' · '+(S.lang==='da'?'øget forbrug':'spending increased'),prompt:(S.lang==='da'?'Sammenlign forbruget i den valgte periode med den forrige lige lange periode, og forklar ændringen med konkrete transaktioner. Fokusér på ':'Compare spending in the selected period with the preceding equal-length period and explain the change using transaction evidence. Focus on ')+name});}
 }
 if(review.total)advisorSignals.push({label:review.total+' '+(S.lang==='da'?'poster klar til gennemgang':'items ready for review'),prompt:S.lang==='da'?'Gennemgå mine ventende Review-poster. Foreslå relevante kategorier eller interne overførsler med begrundelse. Vent med at gemme til jeg godkender.':'Read my pending Review items. Suggest categories or internal transfers with evidence. Wait for my approval before saving.'});
 await mountOverviewAdvisor(data,{mode:S.mode,theme:S.theme,from:flowRange.from,to:flowRange.to,currency:S.currency,insights:advisorSignals.slice(0,2)});
 const loadedBudget=await budgetData;if(loadedBudget.error)throw loadedBudget.error;
 const budget=await budgetUI.overview(main,loadedBudget.value);
 const [wealth,flow,employeeShares]=await extra360;const records=wealth?.records??null,visuals=wealth?.visuals??null;
 if(data.isConnected)mount360(data,{S,t,e,money,date,icon,api},{selected,total,info,upcoming,range:r,records,visuals,budget,flow,employeeShares});
}

const colour=(id,kind='account')=>{if(!id)return 'tone-other';const ids=(kind==='category'?S.categories:S.accounts).map(x=>x.id).sort();const index=ids.indexOf(id);return index<0?'tone-other':'tone-'+(index%10);};
const accountMark=id=>`<span class="colour-label ${colour(id)}"><span class="colour-dot" aria-hidden="true"></span><span>${e(accountName(id))}</span></span>`;
const categoryName=id=>S.categories.find(c=>c.id===id)?.name||t('Uncategorized');
function accountPicker(chosen=S.accountView?.accountId,action='select-account'){return `<details class="account-picker"><summary aria-label="${t('Filter accounts')}">${chosen?accountMark(chosen):t('All accounts')}<span aria-hidden="true">⌄</span></summary><div class="account-options">${input('account-query','Search accounts','','search','autocomplete="off"')}<div class="account-option-list" role="group" aria-label="${t('Choose account')}">${button('All accounts',action,`data-id="" aria-pressed="${!chosen}"`)}${S.accounts.map(a=>`<button type="button" data-action="${action}" data-id="${a.id}" aria-pressed="${chosen===a.id}" data-account-name="${e(a.name.toLocaleLowerCase(locale()))}">${accountMark(a.id)}<small>${e(a.currency)}${!a.accessible?' · '+t('Inactive'):''}</small></button>`).join('')}</div><p id="account-no-results" class="muted" hidden>${t('No accounts found.')}</p></div></details>`;}
function accountTransactions(rows){return `<div class="table-wrap" tabindex="0" role="region" aria-label="${t('Transactions')}"><table class="account-ledger"><thead><tr><th>${t('Date')}</th><th>${t('Description')}</th><th>${t('Account')}</th><th>${t('Category')}</th><th class="amount">${t('Amount')}</th></tr></thead><tbody>${rows.map(x=>`<tr data-account-id="${x.accountId}"><td class="ledger-date">${date(x.bookingDate||x.valueDate)}</td><td class="ledger-description"><button class="quiet" data-action="transaction" data-id="${x.id}">${icon("activity")}<span>${e(x.description)}</span></button>${x.status!=='BOOK'?`<small>${t(x.status==='PDNG'?'Pending':x.status)}</small>`:''}</td><td class="ledger-account">${accountMark(x.accountId)}</td><td class="ledger-category">${x.isInternalTransfer?`<span class="muted">${t('Internal transfers')}</span>`:`<span class="category-choice ${colour(x.categoryId,'category')}"><span class="colour-dot" aria-hidden="true"></span><select aria-label="${t('Category')} · ${e(x.description)}" data-action="classify" data-id="${x.id}" data-version="${e(x.version)}">${opts([['',t('Uncategorized')],...S.categories.map(c=>[c.id,c.name])],x.categoryId||'')}</select></span>`}</td><td class="amount ${x.isInternalTransfer?'muted':x.amount>0?'positive':''}">${x.amount>0?'+':''}${money(x.amount,x.currency)}</td></tr>`).join('')}</tbody></table></div>`;}
async function accounts(main){
 if(!S.accountView)S.accountView={accountId:'',search:'',categoryId:'',offset:0};const v=S.accountView;
 if(v.accountId&&!S.accounts.some(a=>a.id===v.accountId))v.accountId='';
 main.classList.add('accounts-main');const r=range();
 main.insertAdjacentHTML('beforeend',header('Accounts',`<div class="overview-controls"><small id="accounts-sync" class="muted"></small><div class="controls">${periodControls()}</div></div>`)+`<div id="accounts-summary" class="loading">${quietLoading()}</div><div class="atlas-workspace"><aside id="accounts-navigator" class="atlas-navigator loading">${quietLoading()}</aside><section id="bank-balance-history" class="ledger-panel bank-history-panel"></section><section class="ledger-panel atlas-ledger"><div class="ledger-heading"><div class="atlas-ledger-title"><h2>${t(v.accountId?'Transactions':'All transactions')}</h2><div class="atlas-rules">${sectionAction('Rules & categories','#/categories')}</div></div><div class="ledger-filters">${input('ledger-search','Search transactions',v.search,'search',`maxlength="200" placeholder="${t('Search transactions')}"`)}${select('ledger-category','Category',[['',t('All categories')],...S.categories.map(c=>[c.id,c.name])],v.categoryId,'data-action="ledger-category"')}${button('Search','ledger-search')}</div></div><div id="atlas-spending" class="atlas-spending"></div><div id="account-transactions" class="loading">${quietLoading()}</div></section></div>`);
 const scope=new URLSearchParams({...r,currency:S.currency,...(v.accountId?{accountId:v.accountId}:{})});const tx=new URLSearchParams(scope);tx.set('limit',accountPageSize);tx.set('offset',v.offset);if(v.search)tx.set('search',v.search);if(v.categoryId)tx.set('categoryId',v.categoryId);
 const days=Math.round((new Date(r.to+'T12:00:00Z')-new Date(r.from+'T12:00:00Z'))/86400000)+1;
 const previousScope=new URLSearchParams(scope);previousScope.set('from',shift(r.from,-days));previousScope.set('to',shift(r.from,-1));
 const [rows,info,previous,balances]=await Promise.all([api('transactions?'+tx),api('account-insights?'+scope),api('account-insights?'+previousScope),Promise.all(S.accounts.map(a=>api(`accounts/${a.id}/balances?limit=20`)))]);
 S.transactions=rows.items;
 S.accountBalances=balances;
 main.querySelector('#accounts-sync').textContent=t('Last sync')+': '+timestamp(info.coverage.oldestAccountSync);
 accountsUI.render(main,{info,previous,balances,range:r});
 await bankDetailsUI.history(main.querySelector('#bank-balance-history'),r,v.accountId);
 const ledger=main.querySelector('#account-transactions');ledger.className='';ledger.innerHTML=(rows.items.length?accountTransactions(rows.items):empty('No transactions found.',''))+`<div class="pagination">${button('Previous','ledger-page','data-step="-1" '+(v.offset===0?'disabled':''))}<span>${rows.total?v.offset+1:0}–${Math.min(v.offset+accountPageSize,rows.total)} / ${rows.total}</span>${button('Next','ledger-page','data-step="1" '+(v.offset+accountPageSize>=rows.total?'disabled':''))}</div>`;
}

function editAccounts(id=S.accountView?.accountId){
 const account=S.accounts.find(a=>a.id===id)||S.accounts[0];
 const label=a=>{const i=S.accounts.indexOf(a),b=S.accountBalances?.[i]?.find(b=>b.currency===a.currency&&['ITAV','CLAV'].includes(b.type));return a.name+' · '+moneyText(b?.amount,a.currency);};
 dialog.innerHTML=`<div class="dialog-head"><h2>${t('Edit accounts')}</h2>${button('Close','close')}</div>${account?`${select('preferences-account','Account',S.accounts.map(a=>[a.id,label(a)]),account.id,'data-action="preferences-account"')}<form id="account-preferences-form" data-id="${account.id}" data-version="${e(account.version)}" class="form account-preferences">${input('account-custom-name','Account name',account.customName||'','text',`maxlength="200" placeholder="${e(account.providerName)}"`)}<small>${t('Bank name')}: ${e(account.providerName)}. ${t('Leave the name empty to use the bank name.')}</small><div id="account-bank-details" class="muted"></div><label class="review-rule-check"><input id="account-is-savings" type="checkbox" ${account.isSavings?'checked':''}>${t('Savings account')}</label><p class="muted">${t('Include this account in total savings and use its net deposits to calculate available to spend. Your bank data stays unchanged.')}</p><div class="error" role="alert"></div><button class="primary" type="submit">${t('Save changes')}</button></form>`:empty('No accounts found.','')}`;
 if(!dialog.open)dialog.showModal();validateForms();
 const target=dialog.querySelector('#account-bank-details');if(account&&target)api(`accounts/${account.id}/bank-details`).then(result=>{if(!target.isConnected)return;const d=result.details;target.textContent=d?[d.description,d.product,d.type,...d.identifiers.map(i=>i.masked)].filter(Boolean).join(' · '):'';}).catch(()=>{});
}
function overviewMoneyDetails(kind){
 const info=S.overviewInfo;if(!info)return;
 const row=(label,amount)=>`<div class="list-row"><span>${t(label)}</span><strong>${money(amount,S.currency)}</strong></div>`;
 const warnings=[!info.coverage.sufficientHistory?t('Incomplete history'):'',info.excludedUndatedBookedCount?t('Undated entries excluded')+': '+info.excludedUndatedBookedCount:''].filter(Boolean);
 const savingsAccounts=S.accounts.filter(a=>a.currency===S.currency&&a.isSavings);
 dialog.innerHTML=`<div class="dialog-head"><h2>${t(kind==='savings'?'Total savings':'Available to spend')}</h2>${button('Close','close')}</div>${kind==='savings'?`<p class="muted">${t('Current available balances on accounts marked as savings.')} · ${e(S.currency)}</p><div class="list">${savingsAccounts.map(a=>{const i=S.accounts.indexOf(a),b=S.accountBalances?.[i]?.find(b=>b.currency===a.currency&&['ITAV','CLAV'].includes(b.type));return `<div class="list-row"><span>${e(a.name)}</span><strong>${money(b?.amount,a.currency)}</strong></div>`;}).join('')}${row('Total savings',info.totalSavings)}</div>${info.savingsAccountCount&&info.savingsBalanceStale?`<p class="warning">${t('Stale balance')}</p>`:''}`:`<p class="muted">${date(info.from)} – ${date(info.to)}</p><div class="list">${row('Income',info.income)}${row('Expenses',-info.spending)}${row('Net savings deposits',-info.savings)}${row('Available to spend',info.disposableAmount)}</div><p>${t('Income minus expenses minus net savings deposits in the selected period. Savings withdrawals release money; transfers between savings accounts cancel out.')}</p><p class="muted">${t('Booked transactions only. Confirmed internal transfers are excluded from income and expenses. Future bills and planned budget amounts are not included.')}</p>${warnings.length?`<p class="warning">${e(warnings.join(' · '))}</p>`:''}`}${!info.savingsAccountCount?`<p class="warning">${t('No savings accounts selected. Mark your savings accounts to include them.')}</p>`:''}<div class="actions">${button('Edit accounts','edit-accounts')}</div>`;
 dialog.showModal();
}
function reviewState(){return S.review||(S.review={kind:'All',accountId:'',sort:'newest',offset:0,checked:[],selectedKey:null,historyOffset:0});}
const reviewRef=x=>({key:x.key,signature:x.signature});
const reviewKind=x=>t({Categorize:'Categorised',ConfirmTransfer:'Transfer confirmed',Skip:'Snoozed for 24 hours',Dismiss:'Marked as not a transfer'}[x]||x);
function reviewHistoryRows(history){return history.items.length?history.items.map(x=>`<div class="review-history-row"><div><span>${reviewKind(x.kind)}</span><p>${x.count>1?x.count+' '+t('Transactions'):e(x.description)}</p><small>${timestamp(x.createdAt)}${x.undoneAt?' · '+t('Undone'):''}</small></div>${!x.undoneAt?button('Undo','review-undo',`data-id="${x.id}" data-version="${e(x.version)}"`,'quiet'):''}</div>`).join(''):`<p class="muted">${t('No review changes yet.')}</p>`;}
function reviewEntry(x){return `<div class="review-entry"><div>${accountMark(x.accountId)}<p>${e(x.description)}</p><small>${date(x.bookingDate)} · ${t('Booked')}</small></div><strong>${x.amount>0?'+':''}${money(x.amount,x.currency)}</strong></div>`;}
function reviewDetails(){
 const v=reviewState(),data=S.reviewData,detail=document.querySelector('#review-detail');if(!detail)return;
 const checked=data.items.filter(x=>v.checked.includes(x.key)&&x.kind==='Category'),item=data.items.find(x=>x.key===v.selectedKey);
 const chosen=checked.length?checked:item?[item]:[];S.reviewSelected=chosen;
 if(!chosen.length){detail.innerHTML=empty('Select an item','Choose something from the review list.');return;}
 if(chosen.length===1&&chosen[0].kind==='Transfer'){
  const x=chosen[0];detail.innerHTML=`<div class="review-eyebrow">${t('Possible internal transfer')}</div><h2>${t('Do these entries belong together?')}</h2><div class="review-pair">${reviewEntry(x.transaction)}<div class="pair-connector" aria-hidden="true">${icon('connections')}</div>${reviewEntry(x.counterpart)}</div><ul class="match-evidence"><li>${t('Same amount and currency')}</li><li>${t('Same booking date')}</li><li>${t('Different accounts')}</li>${x.evidence==='AccountIdentity'?`<li>${t('The bank account identifier matches your other account.')}</li>`:''}</ul><p class="muted">${t('Confirming excludes both entries from income and spending. Your bank transactions stay unchanged.')}</p><div class="actions">${button('Confirm match','review-confirm','','primary')}${button('Snooze 24h','review-skip')}${button('Not a transfer','review-dismiss','','quiet')}</div><div class="error" role="alert"></div>`;
 }else{
  const bulk=chosen.length>1,x=chosen[0].transaction;
  const similar=data.items.filter(row=>row.kind==='Category'&&row.transaction.description.toLocaleLowerCase()===x.description.toLocaleLowerCase());
  detail.innerHTML=`${bulk?`<div class="review-eyebrow">${t('Category review')}</div><h2>${chosen.length} ${t('Transactions selected')}</h2><div class="review-bulk-list">${chosen.map(row=>`<div>${e(row.transaction.description)}<span>${money(row.transaction.amount,row.transaction.currency)}</span></div>`).join('')}</div>`:`<div class="review-selected-heading"><span class="review-merchant-icon" aria-hidden="true">${icon('accounts')}</span><div><h2>${e(x.description)}</h2><p>${date(x.bookingDate)} · ${accountMark(x.accountId)}</p></div><strong>${x.amount>0?'+':''}${money(x.amount,x.currency)}</strong></div>`}${!bulk&&chosen[0].merchantCategory?(()=>{const suggested=S.categories.find(c=>c.id===chosen[0].suggestedCategoryId)?.name;return `<div class="bank-category-suggestion"><strong>${suggested?`${t('Suggested')}: ${e(suggested)}`:t('No matching category yet')}</strong><small class="bank-category-source">${t('Bank category')}: ${e(t(chosen[0].merchantCategory))}</small><p>${t('Based on the merchant category supplied by the bank. Review before saving; this does not change your categories automatically.')}</p></div>`;})():''}<form id="review-category-form" class="form"><div>${select('review-category','Choose a category',[['',t('Choose a category')],...S.categories.map(c=>[c.id,c.name])],!bulk?(chosen[0].suggestedCategoryId||''):'','required')}${S.categories.length?'':`<p>${sectionAction('Add category','#/categories/new')}</p>`}</div>${!bulk?`<label class="review-rule-check"><input id="review-create-rule" type="checkbox" data-action="review-rule">${t('Use this category for future matching descriptions')}</label><div id="review-rule-fields" hidden>${input('review-rule-contains','Rule contains',x.description.slice(0,200),'text','maxlength="200"')}<small>${t('The rule applies to future imports. Existing transactions are not changed automatically.')}</small></div>`:''}<div class="error" role="alert"></div><div class="actions"><button type="submit" class="primary">${t(bulk?'Apply to selected':'Save category')}</button>${!bulk?button('Snooze 24h','review-skip'):button('Clear selection','review-clear')}</div></form>${!bulk&&similar.length>1?`<div class="review-similar">${button('Select matching items on this page','review-similar',`data-key="${e(chosen[0].key)}"`,'quiet')}<span>${similar.length}</span></div>`:''}`;
 }
 validateForms();
}
function reviewHero(counts){
 return `<section class="review-hero" data-scene="${dayScene()}" aria-label="${e(t('Review summary'))}">${counts.all?'':`<p class="review-caught-up">${t('No items need review in these accounts right now.')}</p>`}<div class="review-hero-footer"><div class="review-hero-counts"><div><strong>${counts.all}</strong><span>${t('To review')}</span></div><div><strong>${counts.categories}</strong><span>${t('Need a category')}</span></div><div><strong>${counts.transfers}</strong><span>${t('Possible transfers')}</span></div></div>${counts.all?`<div class="review-mix" aria-label="${e(counts.categories+' '+t('Need a category')+', '+counts.transfers+' '+t('Possible transfers'))}"><span data-review-share="${counts.categories/counts.all*100}"></span><span data-review-share="${counts.transfers/counts.all*100}"></span></div>`:''}</div></section>`;
}
function reviewInboxRow(x,v){return `<div class="review-row ${v.selectedKey===x.key?'selected':''}" data-review-key="${e(x.key)}">${x.kind==='Category'?`<input type="checkbox" aria-label="${t('Select')} ${e(x.transaction.description)}" data-action="review-check" data-key="${e(x.key)}" ${v.checked.includes(x.key)?'checked':''}>`:`<span class="review-transfer-marker" aria-hidden="true"></span>`}<button type="button" class="review-item" data-action="review-select" data-key="${e(x.key)}" aria-pressed="${v.selectedKey===x.key}"><span class="review-merchant-icon" aria-hidden="true">${icon(x.kind==='Transfer'?'connections':'accounts')}</span><span class="review-item-description">${e(x.transaction.description)}</span><span class="review-item-date">${date(x.transaction.bookingDate)}</span><span class="review-item-account">${accountMark(x.transaction.accountId)}${x.counterpart?` → ${accountMark(x.counterpart.accountId)}`:''}</span><span class="review-item-amount">${money(x.kind==='Transfer'?Math.abs(x.transaction.amount):x.transaction.amount,x.transaction.currency)}</span><span class="review-item-reason ${x.kind==='Transfer'?'transfer':'category'}">${t(x.kind==='Transfer'?'Possible transfer':'Category needed')}</span></button></div>`;}
async function reviewPage(main,historyOnly=false){
 const v=reviewState();main.classList.add('review-main');
 if(historyOnly){S.reviewHistory=await api('review/history?offset='+v.historyOffset);const h=S.reviewHistory;main.insertAdjacentHTML('beforeend',header('Review history',`<a class="back-link" href="#/review">← ${t('Back to review')}</a>`)+`<div class="review-history">${reviewHistoryRows(h)}</div><div class="pagination">${button('Previous','review-history-page','data-step="-1" '+(!v.historyOffset?'disabled':''))}<span>${h.total?v.historyOffset+1:0}–${Math.min(v.historyOffset+10,h.total)} / ${h.total}</span>${button('Next','review-history-page','data-step="1" '+(v.historyOffset+10>=h.total?'disabled':''))}</div>`);return;}
 const query=()=>new URLSearchParams({kind:v.kind,sort:v.sort,offset:v.offset,...(v.accountId?{accountId:v.accountId}:{})});
 let [data,history]=await Promise.all([api('review?'+query()),api('review/history')]);
 if(data.items.length===0&&v.offset>0){v.offset=Math.max(0,Math.floor((data.total-1)/8)*8);data=await api('review?'+query());}
 S.reviewData=data;S.reviewHistory=history;S.reviewCount=data.globalTotal;
 document.querySelectorAll('[data-review-count]').forEach(el=>{el.textContent=data.globalTotal||'';});
 v.checked=v.checked.filter(key=>data.items.some(x=>x.key===key&&x.kind==='Category'));if(!data.items.some(x=>x.key===v.selectedKey))v.selectedKey=data.items[0]?.key||null;
 main.classList.add('review-focus');
 const recent=`<section class="review-recent"><div class="section-head"><h2>${t('Recently reviewed')}</h2>${sectionAction('View history','#/review/history')}</div>${reviewHistoryRows({...history,items:history.items.slice(0,3)})}</section>`;
 main.insertAdjacentHTML('beforeend',header('Review',accountPicker(v.accountId,'review-account'))+reviewHero(data.counts)+`<div class="review-tabs" role="group" aria-label="${t('Review filters')}">${[['All','All',data.counts.all],['Category','Categories',data.counts.categories],['Transfer','Transfers',data.counts.transfers]].map(([key,label,count])=>`<button data-action="review-filter" data-value="${key}" aria-pressed="${v.kind===key}" class="${v.kind===key?'active':''}">${t(label)} <span>${count}</span></button>`).join('')}${sectionAction('Rules & categories','#/categories')}</div>${data.items.length?`<div class="review-layout"><section class="review-inbox"><div class="review-inbox-head"><h2>${t('Needs review')}</h2>${select('review-sort','Sort',[['newest',t('Newest first')],['oldest',t('Oldest first')]],v.sort,'data-action="review-sort"')}</div><div class="review-list">${data.items.map(x=>reviewInboxRow(x,v)).join('')}</div><div class="pagination">${button('Previous','review-page','data-step="-1" '+(!v.offset?'disabled':''))}<span>${v.offset+1}–${Math.min(v.offset+data.items.length,data.total)} / ${data.total}</span>${button('Next','review-page','data-step="1" '+(v.offset+8>=data.total?'disabled':''))}</div></section><aside class="review-detail-column"><div id="review-detail" tabindex="-1" aria-live="polite"></div>${recent}</aside></div>`:`<div class="review-empty-layout"><section class="review-empty"><span class="review-empty-symbol" aria-hidden="true">${icon('review')}</span><div><h2>${t(v.kind!=='All'?'No items match these filters.':'Nothing needs review')}</h2><p>${t(v.kind!=='All'?'Try another review filter.':'New items will appear here when they need a category or a transfer check.')}</p><div class="actions">${v.kind!=='All'?button('Show all items','review-filter','data-value="All"','quiet'):`${sectionAction('View transactions','#/accounts')}`}</div></div></section>${recent}</div>`}`);
 main.querySelectorAll('[data-review-share]').forEach(el=>el.style.width=el.dataset.reviewShare+'%');
 reviewDetails();
}
async function reviewAction(kind,el){
 if(S.saving||!await leave())return;const selected=S.reviewSelected||[];if(!selected.length)return;
 S.saving=true;el.disabled=true;try{await post('review/actions',{kind,items:[reviewRef(selected[0])]});S.review.checked=[];notice(kind==='Skip'?'Snoozed for 24 hours':'Saved');await navigate();}finally{S.saving=false;if(el.isConnected)el.disabled=false;validateForms();}
}

async function activity(main){const f=S.filters;const control=input('search','Search transactions',f.search||'','search')+select('account-filter','Account',[['',t('All accounts')],...S.accounts.map(a=>[a.id,a.name])],f.accountId||'')+select('category-filter','Category',[['',t('All categories')],...S.categories.map(c=>[c.id,c.name])],f.categoryId||'')+select('state-filter','Activity',[['',t('All states')],['BOOK',t('Booked')],['PDNG',t('Pending')]],f.status||'')+input('activity-from','From',f.from||'','date')+input('activity-to','To',f.to||'','date')+button('Search','search');
 main.insertAdjacentHTML('beforeend',header('Activity',`${sectionAction('Rules & categories','#/categories')}`)+`<div class="controls">${control}</div><div id="transactions" class="section loading">${quietLoading()}</div>`);
 const q=new URLSearchParams({offset:S.offset,limit:30,...Object.fromEntries(Object.entries(f).filter(([,v])=>v))});const rows=await api('transactions?'+q);S.transactions=rows.items;
 const target=main.querySelector('#transactions');target.className='section';target.innerHTML=(rows.items.length?activityRows(rows.items,true):empty('No transactions found.',''))+`<div class="pagination">${button('Previous','page','data-step="-1" '+(S.offset===0?'disabled':''))}<span>${rows.total?S.offset+1:0}–${Math.min(S.offset+30,rows.total)} / ${rows.total}</span>${button('Next','page','data-step="1" '+(S.offset+30>=rows.total?'disabled':''))}</div>`;
}
function settings(main){const section=S.section||'appearance';main.insertAdjacentHTML('beforeend',`<div class="settings-mobile"><a class="back-link" href="#/overview">← ${t('Back to Overview')}</a>${brand()}${select('settings-section','Settings',[['profile',t('Profile')],['language',t('Language')],['appearance',t('Appearance')]],section,'data-action="settings-section"')}</div>`);
 const content=section==='appearance'?`${header('Appearance')}<h2>${t('Theme')}</h2><div class="theme-grid" role="group" aria-label="${t('Theme')}">${themes.map(x=>`<button type="button" class="theme-choice ${S.theme===x?'selected':''}" data-action="theme" data-theme-value="${x}" aria-pressed="${S.theme===x}"><span class="theme-preview" data-preview="${x}" aria-hidden="true"><i class="tp-side"></i><i class="tp-card"><b></b><b></b></i><i class="tp-accent"></i><i class="tp-ai"></i><i class="tp-user"></i></span>${t(x[0].toUpperCase()+x.slice(1))} ${S.theme===x?'✓':''}</button>`).join('')}</div><section class="ai-glass-setting"><div><h2>${t('AI Glass')}</h2><p class="muted" id="ai-glass-description">${t('Add a glass finish to AI chat while keeping your theme colors.')}</p><p class="muted small">${t('Refraction in Chrome and Edge; frosted glass in other browsers.')}</p></div><button type="button" role="switch" aria-checked="${S.aiGlass}" aria-label="${t('AI Glass')}" aria-describedby="ai-glass-description" data-action="ai-glass" class="ai-glass-switch"><span></span></button></section><div class="section muted">${t('Custom themes · Later')}</div>`:section==='language'?`${header('Language')}<p class="muted">${t('Your language applies to both Dan and Demo.')}</p>${select('language','Display language',[['en','English'],['da','Dansk']],S.lang,'data-action="language"')}`:`${header('Profile')}<h2>${S.owner?'Dan':'Demo'}</h2><p>${t(S.owner?'Local owner':'Demo workspace')}</p>${S.owner&&!S.passwordConfigured?button('Set your local password','owner-sign-in'):!S.owner?button('Sign in as Dan','owner-sign-in'):''}<p class="muted">${t('Demo uses fictional data. Dan uses your connected accounts.')}</p>${button('Sign out','logout')}`;
 main.insertAdjacentHTML('beforeend',`<section class="settings-content">${content}</section><div class="settings-mobile">${accountSelector()}</div>`);
}
