async function categoriesPage(main){const rules=await api('rules');S.rules=rules;main.insertAdjacentHTML('beforeend',header('Rules & categories',`${sectionAction('Review','#/review')}`)+`<div class="split"><section class="section"><h2>${t('Category')}</h2>${button('Add category','create-category','','primary')}<div class="utility-search">${input("category-query","Search categories","","search")}</div><div class="list utility-list" id="category-list" tabindex="0" role="region" aria-label="${t("Categories")}">${S.categories.map(c=>`<div class="list-row" data-filter-text="${e(c.name)}"><span>${e(c.name)}</span><div>${button('Edit','rename-category',`data-id="${c.id}"`,'quiet')}${button('Delete','delete-category',`data-id="${c.id}" data-version="${e(c.version)}"`,'quiet')}</div></div>`).join('')}</div></section><section class="section"><h2>${t('Add rule')}</h2>${button('Add rule','create-rule','','primary')}<div class="section">${button('Apply rules','apply-rules')}<div class="utility-search">${input('rule-query','Search rules','','search')}</div><div class="list utility-list" id="rule-list" tabindex="0" role="region" aria-label="${t('Rules')}">${rules.map(r=>`<div class="list-row" data-filter-text="${e(r.contains+" "+(S.categories.find(c=>c.id===r.categoryId)?.name||""))}"><div class="grow">${e(r.contains)}<small> → ${e(S.categories.find(c=>c.id===r.categoryId)?.name)}</small></div>${button('Delete','delete-rule',`data-id="${r.id}" data-version="${e(r.version)}"`,'quiet')}</div>`).join('')}</div>${sectionAction('Internal transfers','#/transfers')}</section></div>`);for(const id of ['category-list','rule-list'])main.querySelector('#'+id).insertAdjacentHTML('beforeend',`<p class="utility-no-results" hidden>${t('No matches found.')}</p>`);}
async function connectionsPage(main){const [connections,jobs]=await Promise.all([api('connections'),api('jobs')]);S.connections=connections;main.insertAdjacentHTML('beforeend',header('Connections',button('Add bank','add-bank')+button('Refresh','refresh'))+`<div class="list">${connections.map(c=>`<section class="section"><div class="section-head"><h2>${e(c.bank)}</h2><span class="status ${c.errorCode?'warning':'muted'}">${e(t(c.status))}</span></div><dl class="definition"><dt>${t('Country')}</dt><dd>${e(c.country)}</dd><dt>${t('Consent expires')}</dt><dd>${date(c.validUntil)}</dd><dt>${t('Last sync')}</dt><dd>${date(c.lastSuccess)}</dd></dl>${c.errorCode?`<p class="warning">${e(c.errorCode)}</p>`:''}<div class="actions">${button('Refresh','sync',`data-id="${c.id}"`)}${button('Reconnect','reconnect',`data-id="${c.id}"`)}${button('Disconnect','disconnect',`data-id="${c.id}" data-version="${e(c.version)}"`,'quiet danger')}</div></section>`).join('')}</div>${!connections.length?empty('No connections yet','Connect a bank to see your accounts.') :''}<section class="section"><h2>${t('Import status')}</h2><div class="list">${jobs.slice(0,12).map(j=>`<div class="list-row"><div class="grow">${e(accountName(j.accountId))}<small> · ${e(t(j.status))} · ${j.items} ${t(j.items===1?"entry":"entries")}</small>${j.errorCode?`<p class="warning">${e(j.errorCode)}</p>`:''}</div>${['Failed','Blocked','Paused'].includes(j.status)?button('Retry','retry-job',`data-id="${j.id}" data-version="${e(j.version)}"`):`<small>${date(j.completedAt||j.createdAt)}</small>`}</div>`).join('')}</div></section>`);}
async function transfersPage(main){const [matches,transactions]=await Promise.all([api('transfer-matches'),api('transactions?status=BOOK&limit=200')]);S.transferMatches=matches;const label=x=>`${date(x.bookingDate)} · ${accountName(x.accountId)} · ${x.description} · ${x.amount} ${x.currency}`;main.insertAdjacentHTML('beforeend',header('Internal transfers',`<a class="back-link" href="#/categories">← ${t('Rules & categories')}</a>`)+`<p class="muted">${t('A match excludes both entries from spending and income.')}</p>${transactions.total>transactions.items.length?`<p class="muted">${t("The selectors show the 200 most recent booked transactions.")}</p>`:""}${button('Match transfer','create-transfer','','primary')}<section class="section"><h2>${t('Matched transfers')}</h2>${matches.length?matches.map(m=>`<div class="list-row"><span>${e(m.outgoing?.description||t("Unavailable"))} ↔ ${e(m.incoming?.description||t("Unavailable"))}<small class="entry-subtitle">${m.outgoing?`${date(m.outgoing.bookingDate)} · ${e(accountName(m.outgoing.accountId))} → ${e(accountName(m.incoming?.accountId))} · ${money(Math.abs(m.outgoing.amount),m.outgoing.currency)}`:t("No data")}</small></span>${button('Remove','remove-transfer',`data-id="${m.id}"`,'quiet')}</div>`).join(''):`<p class="muted">${t('No matched transfers')}</p>`}</section>`);}

let creationKind=null;let creationBackground=[];let creationHeaderObserver=null;
function restoreCreationBackground(){for(const [node,id] of creationBackground)if(node.isConnected)node.id=id;creationBackground=[];}
function isolateCreationBackground(){restoreCreationBackground();creationBackground=[...document.querySelectorAll('#main [id]')].map(node=>[node,node.id]);for(const [node,id] of creationBackground)node.id='behind-creation-'+id;}
async function closeCreation(){if(!await leave())return;const restore=creationKind==='budget'||creationKind==='suggestions';creationKind=null;creationHeaderObserver?.disconnect();dialog.close();dialog.className='';dialog.replaceChildren();restoreCreationBackground();if(restore)await navigate();}
async function openCreate(kind,id){
 if(!await leave())return;isolateCreationBackground();creationKind=kind;dialog.className='creation-modal'+(['budget','suggestions'].includes(kind)?' creation-wide':'')+(['goal','goal-edit'].includes(kind)?' gg-form-modal':'');
 creationHeaderObserver?.disconnect();dialog.innerHTML=`<div class="creation-header"><h2 id="creation-title">${t({goal:'Create goal','goal-edit':'Edit goal',budget:'New budget',suggestions:'From transactions',category:'Add category',rule:'Add rule',transfer:'Match transfer'}[kind])}</h2>${button('Close','close')}</div><div class="creation-body"><p>${quietLoading()}</p></div>`;
 if(!dialog.open)dialog.showModal();const body=dialog.querySelector('.creation-body');
 const syncTitle=()=>{const title=body.querySelector('h1')?.textContent;const target=dialog.querySelector('#creation-title');if(title&&target)target.textContent=title;};
 creationHeaderObserver=new MutationObserver(syncTitle);creationHeaderObserver.observe(body,{childList:true,subtree:true,characterData:true});
 try{body.innerHTML='';if(['category','rule','transfer'].includes(kind)){
 let transactions=null;const label=x=>`${date(x.bookingDate)} · ${accountName(x.accountId)} · ${x.description} · ${moneyText(x.amount,x.currency)}`;
 if(kind==='transfer')transactions=await api('transactions?status=BOOK&limit=200');
 body.innerHTML=header({category:'Add category',rule:'Add rule',transfer:'Match transfer'}[kind])+({category:()=>`<form id="category-form" class="form">${input('category-name','Name','','text','required maxlength="80"')}<div class="error" role="alert"></div><button type="submit">${t('Add category')}</button></form>`,rule:()=>`<form id="rule-form" class="form">${input('contains','Rule contains','','text','required maxlength="200"')}${select('rule-category','Category',[['',t('Category')],...S.categories.map(c=>[c.id,c.name])],'','required')}${input('priority','Priority',0,'number','required step="1"')}<div class="error" role="alert"></div><button type="submit">${t('Add rule')}</button></form>`,transfer:()=>`<form id="transfer-form" class="form form-page">${select('outgoing','From',[['',t('Choose transaction')],...transactions.items.filter(x=>x.amount<0).map(x=>[x.id,label(x)])],'','required')}${select('incoming','To',[['',t('Choose transaction')],...transactions.items.filter(x=>x.amount>0).map(x=>[x.id,label(x)])],'','required')}<div class="error" role="alert"></div><button type="submit">${t('Match transfer')}</button></form>`}[kind])();
 }else if(kind==='goal')await goalsPage(body,['goals','new']);else if(kind==='goal-edit')await goalsPage(body,['goals',id,'edit']);else await budgetUI.render(body,['budgets',kind==='suggestions'?'suggestions':'new']);
 syncTitle();validateForms();body.querySelector('input:not([type=hidden]),select,textarea')?.focus();}
 catch(err){if(!err.stale)body.innerHTML=`<p class="error" role="alert">${e(errorText(err))}</p>`;}
}
function value(id){return (creationKind?dialog.querySelector('#'+id):document.getElementById(id))?.value||'';}
let discardDialog=null,discardPending=null;
function confirmDiscard(){
 if(discardPending)return discardPending;
 const origin=document.activeElement;
 if(!discardDialog){discardDialog=document.createElement('dialog');discardDialog.id='unsaved-changes';discardDialog.className='discard-dialog';discardDialog.setAttribute('aria-labelledby','discard-title');discardDialog.setAttribute('aria-describedby','discard-description');document.body.append(discardDialog);}
 discardDialog.innerHTML=`<div class="discard-symbol" aria-hidden="true">${icon('save')}</div><h2 id="discard-title">${t('Leave without saving?')}</h2><p id="discard-description">${t('Your changes have not been saved. Keep editing, or discard them and continue.')}</p><div class="discard-actions"><button type="button" class="discard-choice" data-discard="yes">${t('Discard changes')}</button><button type="button" class="primary" data-discard="no" autofocus>${t('Keep editing')}</button></div>`;
 discardPending=new Promise(resolve=>{
  const finish=discard=>{discardDialog.close();discardPending=null;if(origin?.isConnected)origin.focus({preventScroll:true});resolve(discard);};
  discardDialog.onclick=event=>{const choice=event.target.closest('[data-discard]');if(choice)finish(choice.dataset.discard==='yes');};
  discardDialog.oncancel=event=>{event.preventDefault();finish(false);};
 });
 discardDialog.showModal();discardDialog.querySelector('[data-discard="no"]').focus();return discardPending;
}
async function leave(){if(S.saving)return false;const seq=S.seq;if(S.dirty&&!await confirmDiscard())return false;if(seq!==S.seq)return false;S.dirty=false;return true;}
function confirmAction(message){
 const origin=document.activeElement,modal=document.createElement('dialog');modal.className='discard-dialog';modal.setAttribute('aria-label',t('Confirm'));
 modal.innerHTML=`<h2>${t('Confirm')}</h2><p>${e(message)}</p><div class="discard-actions"><button type="button" data-choice="yes">${t('Confirm')}</button><button type="button" class="primary" data-choice="no" autofocus>${t('Cancel')}</button></div>`;document.body.append(modal);
 return new Promise(resolve=>{const finish=value=>{modal.close();modal.remove();if(origin?.isConnected)origin.focus({preventScroll:true});resolve(value);};modal.onclick=event=>{const button=event.target.closest('[data-choice]');if(button)finish(button.dataset.choice==='yes');};modal.oncancel=event=>{event.preventDefault();finish(false);};modal.showModal();modal.querySelector('[data-choice="no"]').focus();});
}
